package system

import (
	"fmt"

	"github.com/Masterminds/semver/v3"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// checkMinCLI returns an OnManifest hook that refuses to render a template
// whose spec.minCLI exceeds this CLI's build version: the template renders
// from a value contract this build may not assemble. A template without
// minCLI passes, and so does any non-semver build version ("dev", "") —
// local development builds must render every template.
func checkMinCLI(cliVersion string) func(*template.Template) error {
	return func(t *template.Template) error {
		min := t.Spec.MinCLI
		if min == "" {
			return nil
		}
		if _, err := semver.NewVersion(cliVersion); err != nil {
			return nil
		}
		current := semver.MustParse(cliVersion)
		if current.LessThan(semver.MustParse(min)) {
			return fmt.Errorf("template %s requires intropy %s or newer (this is %s)\nupgrade intropy, or render with --template-version <older tag>",
				t.Metadata.Name, min, cliVersion)
		}
		return nil
	}
}

package gitops

import (
	"errors"
	"fmt"
	"io"
	"io/fs"
	"maps"
	"os"
	"path/filepath"
	"slices"
	"strings"

	"gopkg.in/yaml.v3"
)

const (
	// DeployFileName is the repository-level contract, at the root of the
	// GitOps repository. Its presence is what marks a repository as one this
	// CLI may deploy through.
	DeployFileName = "deploy.yaml"

	// ComponentFileName is the per-component contract, in the component
	// directory alongside base/ and overlays/.
	ComponentFileName = "component.yaml"

	// DomainsDirName is the root of the coordinate tree.
	DomainsDirName = "domains"

	// OverlaysDirName holds one directory per environment.
	OverlaysDirName = "overlays"

	// SchemaVersion is the newest schema this CLI understands for both files.
	// Bump only for incompatible changes; new optional fields do not require
	// a bump.
	SchemaVersion = 1

	// SyncAuto and SyncManual are the recognised environment sync policies.
	// Manual environments are gated in ArgoCD, so deploy commits and pushes
	// but must not wait for a sync that will never start on its own.
	SyncAuto   = "auto"
	SyncManual = "manual"

	// KindService and KindShared are the recognised component kinds.
	//
	// A service is a workload with an image for deploy to pin. A shared
	// component holds the system-level objects that belong to no single
	// workload — the Dapr components a system's blocks resolve by name, and the
	// secrets behind them. Exactly one ArgoCD Application must own each of
	// those objects, and a shared component is what gives them that owner.
	//
	// KindService is the default, so a component.yaml predating this field is
	// unchanged in meaning.
	KindService = "service"
	KindShared  = "shared"
)

// DeployConfig is the parsed deploy.yaml.
type DeployConfig struct {
	SchemaVersion int    `yaml:"schemaVersion"`
	Registry      string `yaml:"registry"`

	// MinimumCliVersion, when set, is the oldest CLI the repository's authors
	// consider safe to deploy with.
	MinimumCliVersion string `yaml:"minimumCliVersion"`

	// Platform describes the target cluster's hosting. It is repo-wide on
	// purpose: a system's Dapr components are identical in every environment,
	// so there is nothing for an environment to override. Only manifest
	// scaffolding reads it; deploy, promote, diff and sync ignore it entirely.
	Platform PlatformConfig `yaml:"platform"`

	Argocd       ArgocdConfig                 `yaml:"argocd"`
	Environments map[string]EnvironmentConfig `yaml:"environments"`
}

// PlatformConfig names the hosting choices a manifest skeleton renders against.
//
// The values are deliberately not validated here. The allowed set belongs to
// whichever template consumes them — its JSON Schema is where the enum lives —
// and hard-coding a list here would mean a CLI release for every new broker.
type PlatformConfig struct {
	// Provider is the hosting environment, e.g. "azure" or "beebyte".
	Provider string `yaml:"provider"`

	// Pubsub selects the Dapr pub/sub building block, e.g. "in-memory",
	// "rabbitmq" or "servicebus".
	Pubsub string `yaml:"pubsub"`

	// SecretStore selects the Dapr secret store, e.g. "kubernetes",
	// "azure.keyvault" or "vault".
	SecretStore string `yaml:"secretStore"`
}

// ArgocdConfig locates the ArgoCD instance that reconciles this repository.
type ArgocdConfig struct {
	Server string `yaml:"server"`

	// AppNamespace is the namespace the Application objects live in. It is not
	// optional in practice: the ApplicationSets are deployed per customer
	// (e.g. customer-wsf) rather than into argocd, and omitting appNamespace
	// from an API call against such an installation returns a 404 that is
	// indistinguishable from "no such application".
	AppNamespace string `yaml:"appNamespace"`
}

// EnvironmentConfig is one entry under environments.
type EnvironmentConfig struct {
	// Sync is "auto" or "manual".
	Sync string `yaml:"sync"`

	// PromotesFrom lists environments a promotion into this one may draw
	// from. Deploy reads it to report whether the digests being deployed are
	// what those environments already run; enforcing it is the promote
	// command's job.
	PromotesFrom []string `yaml:"promotesFrom"`

	// RequireSourceHealthy demands the source environment be healthy before a
	// promotion into this one. Parsed here, enforced by promote.
	RequireSourceHealthy bool `yaml:"requireSourceHealthy"`

	// Scratch marks an environment as disposable. The semantics are not yet
	// defined, so this is carried but never acted on — parsing it now means a
	// repository that already sets it is not rejected as malformed.
	Scratch bool `yaml:"scratch"`
}

// ComponentConfig is the parsed component.yaml.
type ComponentConfig struct {
	SchemaVersion int    `yaml:"schemaVersion"`
	Name          string `yaml:"name"`

	// Kind is KindService or KindShared; empty means KindService, so every
	// component.yaml written before this field existed keeps working.
	Kind string `yaml:"kind"`

	// SourcePaths are the paths in the *source* repository that make up this
	// component. The working-tree cleanliness check is scoped to them, so an
	// unrelated dirty file elsewhere in a monorepo does not block a deploy.
	SourcePaths []string `yaml:"sourcePaths"`

	// Images are the image repositories to pin. Explicit rather than derived:
	// existing repositories name images inconsistently, and a wrong guess
	// silently adds an inert images[] entry instead of failing.
	Images []ImageRef `yaml:"images"`

	// Environments are the environments this component may deploy to.
	Environments []string `yaml:"environments"`
}

// ImageRef names one image repository, without a tag or digest.
type ImageRef struct {
	Name string `yaml:"name"`
}

// LoadDeployConfig reads and validates deploy.yaml from the root of a GitOps
// repository.
func LoadDeployConfig(root string) (*DeployConfig, error) {
	path := filepath.Join(root, DeployFileName)
	var cfg DeployConfig
	if err := decodeFile(path, &cfg); err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil, fmt.Errorf("%s has no %s, so it is not a GitOps repository this CLI can deploy through", root, DeployFileName)
		}
		return nil, err
	}
	if err := cfg.validate(path); err != nil {
		return nil, err
	}
	return &cfg, nil
}

func (c *DeployConfig) validate(path string) error {
	if err := checkSchemaVersion(path, c.SchemaVersion); err != nil {
		return err
	}
	if c.Registry == "" {
		return fmt.Errorf("%s: registry is required", path)
	}
	if len(c.Environments) == 0 {
		return fmt.Errorf("%s: at least one entry under environments is required", path)
	}
	for _, name := range slices.Sorted(maps.Keys(c.Environments)) {
		env := c.Environments[name]
		switch env.Sync {
		case SyncAuto, SyncManual:
		case "":
			return fmt.Errorf("%s: environment %q has no sync policy (expected %q or %q)", path, name, SyncAuto, SyncManual)
		default:
			return fmt.Errorf("%s: environment %q has sync %q (expected %q or %q)", path, name, env.Sync, SyncAuto, SyncManual)
		}
		for _, src := range env.PromotesFrom {
			if _, ok := c.Environments[src]; !ok {
				return fmt.Errorf("%s: environment %q promotes from %q, which is not defined", path, name, src)
			}
		}
	}
	return nil
}

// Environment returns the named environment's policy, or an error listing the
// environments the repository does define.
func (c *DeployConfig) Environment(name string) (EnvironmentConfig, error) {
	env, ok := c.Environments[name]
	if !ok {
		return EnvironmentConfig{}, fmt.Errorf("unknown environment %q; %s defines: %s", name, DeployFileName, strings.Join(c.EnvironmentNames(), ", "))
	}
	return env, nil
}

// EnvironmentNames returns the defined environment names in sorted order.
func (c *DeployConfig) EnvironmentNames() []string {
	return slices.Sorted(maps.Keys(c.Environments))
}

// PromotionOrder returns the environments in the order changes flow through
// them: an environment comes after every environment it promotes from. Ties
// break alphabetically, so the order is stable across runs.
//
// EnvironmentNames sorts alphabetically, which renders the usual three as dev,
// prod, staging. That is the wrong story for anything presenting environments
// as a pipeline — the promotion graph is what says prod comes last.
func (c *DeployConfig) PromotionOrder() []string {
	// Sources counts the not-yet-emitted environments each one promotes from.
	// An edge naming an undefined environment is impossible here: validate
	// rejects the file first.
	remaining := make(map[string]int, len(c.Environments))
	for name, env := range c.Environments {
		sources := 0
		for _, src := range env.PromotesFrom {
			// A self-edge is not a dependency on anything else, and counting it
			// would make the environment permanently unemittable.
			if src != name {
				sources++
			}
		}
		remaining[name] = sources
	}

	order := make([]string, 0, len(c.Environments))
	for len(remaining) > 0 {
		ready := make([]string, 0, len(remaining))
		for name, sources := range remaining {
			if sources == 0 {
				ready = append(ready, name)
			}
		}

		// Nothing is ready, so the remainder is a cycle. deploy.yaml's
		// validation does not forbid one, and dropping those environments would
		// hide them from a caller listing what exists — emit them alphabetically
		// instead.
		if len(ready) == 0 {
			order = append(order, slices.Sorted(maps.Keys(remaining))...)
			break
		}

		slices.Sort(ready)
		order = append(order, ready...)
		for _, name := range ready {
			delete(remaining, name)
		}
		// Emitting a whole rank at a time keeps siblings adjacent and
		// alphabetical, rather than interleaving them by discovery order.
		for _, name := range ready {
			for other, env := range c.Environments {
				if _, pending := remaining[other]; !pending {
					continue
				}
				for _, src := range env.PromotesFrom {
					if src == name {
						remaining[other]--
					}
				}
			}
		}
	}
	return order
}

// LoadComponentConfig reads and validates a component.yaml from a component
// directory.
func LoadComponentConfig(dir string) (*ComponentConfig, error) {
	path := filepath.Join(dir, ComponentFileName)
	var cfg ComponentConfig
	if err := decodeFile(path, &cfg); err != nil {
		return nil, err
	}
	if err := cfg.validate(path); err != nil {
		return nil, err
	}
	return &cfg, nil
}

func (c *ComponentConfig) validate(path string) error {
	if err := checkSchemaVersion(path, c.SchemaVersion); err != nil {
		return err
	}
	if c.Name == "" {
		return fmt.Errorf("%s: name is required", path)
	}
	switch c.Kind {
	case "", KindService, KindShared:
	default:
		return fmt.Errorf("%s: kind %q is not valid (expected %q or %q)", path, c.Kind, KindService, KindShared)
	}
	if c.IsShared() {
		// An images entry that matches nothing is inert rather than fatal, so a
		// shared component listing one would look pinnable and never be pinned.
		if len(c.Images) > 0 {
			return fmt.Errorf("%s: kind %q must not declare images — there is no workload to pin", path, KindShared)
		}
	} else if len(c.Images) == 0 {
		return fmt.Errorf("%s: at least one entry under images is required — there is nothing to pin otherwise", path)
	}
	for i, img := range c.Images {
		if img.Name == "" {
			return fmt.Errorf("%s: images[%d] has no name", path, i)
		}
		if hasTagOrDigest(img.Name) {
			return fmt.Errorf("%s: images[%d] name %q must be a bare repository, without a tag or digest", path, i, img.Name)
		}
	}
	if len(c.Environments) == 0 {
		return fmt.Errorf("%s: at least one entry under environments is required", path)
	}
	return nil
}

// SupportsEnvironment reports whether the component declares env.
func (c *ComponentConfig) SupportsEnvironment(env string) bool {
	return slices.Contains(c.Environments, env)
}

// IsShared reports whether the component holds system-level objects rather than
// a workload, and so has nothing for deploy or promote to pin.
func (c *ComponentConfig) IsShared() bool {
	return c.Kind == KindShared
}

// hasTagOrDigest reports whether an image reference carries a tag or digest.
//
// Only the final path segment is examined, because a colon earlier in the
// reference is a registry port: localhost:5555/integrations/app and
// harbor.example.com:8443/app are perfectly ordinary repositories, and
// rejecting them would rule out every registry not on the default port.
func hasTagOrDigest(image string) bool {
	last := image
	if i := strings.LastIndex(image, "/"); i >= 0 {
		last = image[i+1:]
	}
	return strings.ContainsAny(last, ":@")
}

func checkSchemaVersion(path string, got int) error {
	switch {
	case got == 0:
		return fmt.Errorf("%s: schemaVersion is required", path)
	case got > SchemaVersion:
		return fmt.Errorf("%s: schemaVersion %d is newer than this CLI supports (%d); upgrade intropy", path, got, SchemaVersion)
	case got < 1:
		return fmt.Errorf("%s: schemaVersion %d is not valid", path, got)
	}
	return nil
}

// decodeFile decodes a YAML file, rejecting unknown fields so that a
// misspelled key is a loud error rather than a setting that silently does
// nothing.
func decodeFile(path string, into any) error {
	f, err := os.Open(path)
	if err != nil {
		// Wrapped, so callers can still test for fs.ErrNotExist.
		return fmt.Errorf("read %s: %w", path, err)
	}
	defer f.Close()

	dec := yaml.NewDecoder(f)
	dec.KnownFields(true)
	if err := dec.Decode(into); err != nil {
		if errors.Is(err, io.EOF) {
			return fmt.Errorf("parse %s: file is empty", path)
		}
		return fmt.Errorf("parse %s: %w", path, err)
	}
	return nil
}

// Package system assembles scaffolded integrations into a system host. It
// scans the workspace for the .intropy/scaffold.json records `int create`
// left behind, validates them into a system model, and builds the value
// payload the system-host template renders every declaration file from —
// Topics.cs, Connectors.cs, the development and system definitions, and
// the csproj. The template library owns all generated content; this
// package owns workspace knowledge only.
package system

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/huandu/xstrings"

	"github.com/integrio-intropy/intropy-cli/internal/template"
)

// hostTemplate is the directory in the templates repo holding the system
// host: the shell plus every declaration file, rendered from the payload.
const hostTemplate = "system-host"

type CreateOptions struct {
	Name       string // system name as typed; PascalCase or kebab-case
	StartDir   string // workspace scan root; default "."
	OutputDir  string // default: the kebab-cased name
	Version    string // template release tag; default: latest
	CLIVersion string // this build's version, checked against the template's spec.minCLI; non-semver ("dev") skips the gate
	Force      bool
	OutputJSON string // path to write CreateResult JSON; "-" means stdout
	Stdout     io.Writer
	Stderr     io.Writer
	HTTP       *http.Client
	UserAgent  string

	// Owner and Repo select the template library; zero values target the
	// official library. GitHubBaseURL is a test-only seam.
	Owner         string
	Repo          string
	GitHubBaseURL string
}

// CreateResult is the machine-readable summary written when --output-json
// is set. Field names are stable and additive-only.
type CreateResult struct {
	Template  string         `json:"template"`
	Owner     string         `json:"owner"`
	Repo      string         `json:"repo"`
	Version   string         `json:"version"`
	OutputDir string         `json:"outputDir"`
	Values    map[string]any `json:"values"`
	System    Summary        `json:"system"`
}

// Summary describes the assembled system; it loosely mirrors the model the
// host's `graph` verb prints.
type Summary struct {
	Name          string      `json:"name"`
	Components    []Component `json:"components"`
	Topics        []Topic     `json:"topics"`
	Connectors    []Connector `json:"connectors,omitempty"`
	SharedLibrary string      `json:"sharedLibrary"` // scaffold directory
}

func (o *CreateOptions) applyDefaults() {
	if o.StartDir == "" {
		o.StartDir = "."
	}
	if o.Stdout == nil {
		o.Stdout = os.Stdout
	}
	if o.Stderr == nil {
		o.Stderr = os.Stderr
	}
	if o.UserAgent == "" {
		o.UserAgent = "intropy-cli"
	}
}

// Create runs the full assembly: scan the workspace for scaffold records,
// validate them into a system model, build the value payload, and render
// the system-host template with it. All local validation happens before
// any network I/O.
func Create(ctx context.Context, opts CreateOptions) error {
	opts.applyDefaults()
	if opts.Name == "" {
		return fmt.Errorf("a system name is required")
	}

	// Exact parity with the templates' `{{ .name | kebabcase }}`: sprig
	// delegates to xstrings, so OrderFlow and order-flow are equivalent.
	kebab := xstrings.ToKebabCase(opts.Name)
	if opts.OutputDir == "" {
		opts.OutputDir = kebab
	}

	entries, warnings := template.ListScaffolds(opts.StartDir)
	for _, w := range warnings {
		fmt.Fprintf(opts.Stderr, "warning: %v\n", w)
	}
	warnf := func(format string, args ...any) {
		fmt.Fprintf(opts.Stderr, "warning: "+format+"\n", args...)
	}
	model, err := Assemble(entries, warnf)
	if err != nil {
		return err
	}
	model.Name = kebab

	payload, err := buildPayload(model, opts.OutputDir, kebab)
	if err != nil {
		return err
	}

	if err := template.Create(ctx, template.CreateOptions{
		Template:      hostTemplate,
		OutputDir:     opts.OutputDir,
		Version:       opts.Version,
		SetValues:     payload,
		Force:         opts.Force,
		NoInput:       true, // the template's values come from the payload, never prompts
		Stdin:         strings.NewReader(""),
		Stdout:        opts.Stdout,
		Stderr:        opts.Stderr,
		HTTP:          opts.HTTP,
		UserAgent:     opts.UserAgent,
		Owner:         opts.Owner,
		Repo:          opts.Repo,
		GitHubBaseURL: opts.GitHubBaseURL,
		OnManifest:    checkMinCLI(opts.CLIVersion),
	}); err != nil {
		return err
	}

	// The template derives projectName/systemClass from the name; reading
	// them back from the record it just wrote keeps the result summary
	// honest about what was rendered.
	record, err := template.LoadScaffold(filepath.Join(opts.OutputDir, filepath.FromSlash(template.ScaffoldRelPath)))
	if err != nil {
		return err
	}
	hostEntry := template.ScaffoldEntry{Path: opts.OutputDir, Scaffold: *record}
	if model.ProjectName, err = stringValue(hostEntry, "projectName"); err != nil {
		return fmt.Errorf("template %s did not derive the host project name: %w", hostTemplate, err)
	}
	if model.SystemClass, err = stringValue(hostEntry, "systemClass"); err != nil {
		return fmt.Errorf("template %s did not derive the system class name: %w", hostTemplate, err)
	}

	fmt.Fprintf(opts.Stderr, "assembled system %q: %d component(s), %d topic(s), %d connector(s), contracts from %s\n",
		model.Name, len(model.Components), len(model.Topics), len(model.Connectors), model.Shared.Path)

	return maybeWriteCreateResult(opts, record, model)
}

func maybeWriteCreateResult(opts CreateOptions, record *template.Scaffold, model *Model) error {
	if opts.OutputJSON == "" {
		return nil
	}
	absOut, err := filepath.Abs(opts.OutputDir)
	if err != nil {
		absOut = opts.OutputDir
	}
	result := CreateResult{
		Template:  hostTemplate,
		Owner:     record.Owner,
		Repo:      record.Repo,
		Version:   record.Version,
		OutputDir: absOut,
		Values:    record.Values,
		System: Summary{
			Name:          model.Name,
			Components:    model.Components,
			Topics:        model.Topics,
			Connectors:    model.Connectors,
			SharedLibrary: model.Shared.Path,
		},
	}
	data, err := json.MarshalIndent(result, "", "  ")
	if err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	data = append(data, '\n')
	if opts.OutputJSON == "-" {
		if _, err := opts.Stdout.Write(data); err != nil {
			return fmt.Errorf("write --output-json: %w", err)
		}
		return nil
	}
	if err := os.WriteFile(opts.OutputJSON, data, 0o644); err != nil {
		return fmt.Errorf("write --output-json: %w", err)
	}
	return nil
}

package template

import (
	"fmt"
	"os"

	"gopkg.in/yaml.v3"
)

const (
	APIVersionV1 = "intropy.dev/v1"
	KindTemplate = "Template"
)

// Template is the on-disk manifest for a template. The envelope mirrors the
// Kubernetes / Backstage shape so authors recognize it at a glance; the body
// is a deliberately narrow subset (no ui: extensions, no step pipeline).
type Template struct {
	APIVersion string   `yaml:"apiVersion"`
	Kind       string   `yaml:"kind"`
	Metadata   Metadata `yaml:"metadata"`
	Spec       Spec     `yaml:"spec"`
}

type Metadata struct {
	Name        string            `yaml:"name"`
	Title       string            `yaml:"title,omitempty"`
	Description string            `yaml:"description,omitempty"`
	Tags        []string          `yaml:"tags,omitempty"`
	Labels      map[string]string `yaml:"labels,omitempty"`
}

type Spec struct {
	Parameters   map[string]any    `yaml:"parameters"`
	Values       map[string]string `yaml:"values,omitempty"`
	Files        []FileRule        `yaml:"files,omitempty"`
	Dependencies []DependencySpec  `yaml:"dependencies,omitempty"`

	// MinCLI is the minimum CLI version (SemVer) that may render this
	// template. Optional and unenforced by the engine itself; callers
	// compare it against their own build version (see the OnManifest hook
	// on CreateOptions) so a template that expects a newer value contract
	// fails before rendering instead of at the consumer's build.
	MinCLI string `yaml:"minCLI,omitempty"`

	// parameterOrder captures the declaration order of properties in
	// spec.parameters.properties, since Go maps don't preserve YAML order.
	// Populated by UnmarshalYAML.
	parameterOrder []string
}

// FileRule conditionally includes part of a skeleton, so one template can serve
// platforms whose manifest sets differ rather than only whose values differ.
//
// Path is a slash-separated glob relative to skeleton/, matched against the
// *source* path with any .tmpl suffix included — a rule that decides on values
// cannot depend on a path those values produce, so a templated directory segment
// is only reachable via a glob. A trailing "/**" also matches everything beneath
// the directory, and prunes it before its contents are parsed.
//
// When is a Go template (sprig available) rendered against the resolved values.
// Any result other than "", "false" or "0" includes the match.
//
// The first rule whose Path matches decides, and a path no rule matches is
// included — so a template without spec.files renders exactly as it did before
// this field existed.
type FileRule struct {
	Path string `yaml:"path" json:"path"`
	When string `yaml:"when" json:"when"`
}

// DependencySpec declares another template in the same library that must
// exist as a sibling of this template's output. Create renders it when the
// target directory is missing and skips it when a scaffold record from the
// same template is already there, so a shared project is created exactly
// once no matter how many components declare it.
type DependencySpec struct {
	// Template is the dependency's directory name in the templates repo.
	Template string `yaml:"template" json:"template"`
	// Output is a Go template (with sprig) rendered against the parent's
	// resolved values. It must produce a single path segment; the dependency
	// is created as a sibling of the parent's output directory.
	Output string `yaml:"output" json:"output"`
	// Values maps dependency parameter names to Go templates rendered
	// against the parent's resolved values. Dependencies resolve without
	// prompting, so together with the dependency's own defaults these must
	// cover every required parameter.
	Values map[string]string `yaml:"values,omitempty" json:"values,omitempty"`
}

// UnmarshalYAML decodes the spec and captures property declaration order
// so Fields() can return FieldSpecs in author-intended sequence.
func (s *Spec) UnmarshalYAML(node *yaml.Node) error {
	// Every field of Spec must be repeated here: the decode targets rawSpec, so
	// a field added to Spec alone is silently dropped.
	type rawSpec struct {
		Parameters   map[string]any    `yaml:"parameters"`
		Values       map[string]string `yaml:"values,omitempty"`
		Files        []FileRule        `yaml:"files,omitempty"`
		Dependencies []DependencySpec  `yaml:"dependencies,omitempty"`
		MinCLI       string            `yaml:"minCLI,omitempty"`
	}
	var r rawSpec
	if err := node.Decode(&r); err != nil {
		return err
	}
	s.Parameters = r.Parameters
	s.Values = r.Values
	s.Files = r.Files
	s.Dependencies = r.Dependencies
	s.MinCLI = r.MinCLI
	s.parameterOrder = extractPropertyOrder(node)
	return nil
}

func extractPropertyOrder(specNode *yaml.Node) []string {
	if specNode.Kind != yaml.MappingNode {
		return nil
	}
	paramsNode := childByKey(specNode, "parameters")
	if paramsNode == nil {
		return nil
	}
	propsNode := childByKey(paramsNode, "properties")
	if propsNode == nil || propsNode.Kind != yaml.MappingNode {
		return nil
	}
	order := make([]string, 0, len(propsNode.Content)/2)
	for i := 0; i < len(propsNode.Content); i += 2 {
		order = append(order, propsNode.Content[i].Value)
	}
	return order
}

func childByKey(mapping *yaml.Node, key string) *yaml.Node {
	if mapping.Kind != yaml.MappingNode {
		return nil
	}
	for i := 0; i < len(mapping.Content); i += 2 {
		if mapping.Content[i].Value == key {
			return mapping.Content[i+1]
		}
	}
	return nil
}

// FieldSpec is the prompter/CLI view of a single property in spec.parameters.
// Prompters and form code only consume FieldSpecs — they never touch the raw
// JSON Schema map.
type FieldSpec struct {
	Name        string
	Title       string
	Description string
	Type        string // "string" | "boolean" | "integer" | "number"
	Enum        []any
	Default     any
	Pattern     string
	Required    bool
}

// Fields returns the JSON Schema properties as FieldSpecs in YAML declaration
// order.
func (t *Template) Fields() []FieldSpec {
	props, _ := t.Spec.Parameters["properties"].(map[string]any)
	if props == nil {
		return nil
	}
	required := map[string]bool{}
	if list, ok := t.Spec.Parameters["required"].([]any); ok {
		for _, r := range list {
			if s, ok := r.(string); ok {
				required[s] = true
			}
		}
	}
	out := make([]FieldSpec, 0, len(t.Spec.parameterOrder))
	for _, name := range t.Spec.parameterOrder {
		raw, _ := props[name].(map[string]any)
		out = append(out, fieldFromSchema(name, raw, required[name]))
	}
	return out
}

func fieldFromSchema(name string, schema map[string]any, required bool) FieldSpec {
	f := FieldSpec{Name: name, Required: required}
	if schema == nil {
		return f
	}
	f.Type, _ = schema["type"].(string)
	f.Title, _ = schema["title"].(string)
	f.Description, _ = schema["description"].(string)
	f.Pattern, _ = schema["pattern"].(string)
	f.Default = schema["default"]
	if e, ok := schema["enum"].([]any); ok {
		f.Enum = e
	}
	return f
}

// LoadTemplate reads and validates a template.yaml file.
func LoadTemplate(path string) (*Template, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read template: %w", err)
	}
	var t Template
	if err := yaml.Unmarshal(data, &t); err != nil {
		return nil, fmt.Errorf("parse template: %w", err)
	}
	if err := t.validate(); err != nil {
		return nil, fmt.Errorf("invalid template: %w", err)
	}
	return &t, nil
}

func (t *Template) validate() error {
	if t.APIVersion != APIVersionV1 {
		return fmt.Errorf("unsupported apiVersion %q (want %q)", t.APIVersion, APIVersionV1)
	}
	if t.Kind != KindTemplate {
		return fmt.Errorf("unsupported kind %q (want %q)", t.Kind, KindTemplate)
	}
	if t.Metadata.Name == "" {
		return fmt.Errorf("metadata.name is required")
	}
	if t.Spec.Parameters == nil {
		return fmt.Errorf("spec.parameters is required")
	}
	if typ, _ := t.Spec.Parameters["type"].(string); typ != "object" {
		return fmt.Errorf(`spec.parameters.type must be "object"`)
	}
	for i, rule := range t.Spec.Files {
		if rule.Path == "" {
			return fmt.Errorf("spec.files[%d]: path is required", i)
		}
		// A rule with no condition either does nothing or means the author
		// forgot the condition; neither deserves to render.
		if rule.When == "" {
			return fmt.Errorf("spec.files[%d] (%s): when is required", i, rule.Path)
		}
		// Parsed here so a syntax error surfaces at load time rather than
		// partway through a render.
		if _, err := compileExpr(rule.When); err != nil {
			return fmt.Errorf("spec.files[%d] (%s): invalid when: %w", i, rule.Path, err)
		}
	}
	for i, dep := range t.Spec.Dependencies {
		if err := validateTemplateName(dep.Template); err != nil {
			return fmt.Errorf("spec.dependencies[%d]: %w", i, err)
		}
		if dep.Output == "" {
			return fmt.Errorf("spec.dependencies[%d] (%s): output is required", i, dep.Template)
		}
	}
	return nil
}

