// TestCreateMinCLIGateFails covers new CLI + old template era mismatch in
// the other direction: the template declares a minimum CLI version newer
// than this build.
func TestCreateMinCLIGateFails(t *testing.T) {
	files := systemHostFiles()
	files["system-host/template.yaml"] = systemHostTemplateYAML + "  minCLI: '9.9.9'\n"
	srv, _ := newSystemHostServer(t, "v1", files)
	defer srv.Close()

	ws := writeWorkspace(t)
	outDir := filepath.Join(ws, "system-host")
	_, _, err := runCreate(t, srv, CreateOptions{
		Name:       "OrderFlow",
		StartDir:   ws,
		OutputDir:  outDir,
		Version:    "v1",
		CLIVersion: "0.4.0",
	})
	if err == nil {
		t.Fatal("expected the minCLI gate to fail")
	}
	if !strings.Contains(err.Error(), "requires intropy 9.9.9 or newer (this is 0.4.0)") {
		t.Errorf("err = %v, want the version gate message", err)
	}
	if !strings.Contains(err.Error(), "--template-version") {
		t.Errorf("err = %v, want the --template-version remedy", err)
	}
	if _, statErr := os.Stat(outDir); !os.IsNotExist(statErr) {
		t.Errorf("the gate must run before any output is written; %s exists", outDir)
	}
}

